import pytest

def test_pre_init_no_args():
    @attr.s
    class A:
        x: int
        def __attrs_pre_init__(self):
            self.x = 10

    a = A(1)
    assert a.x == 10

def test_pre_init_with_args():
    @attr.s
    class B:
        x: int
        def __attrs_pre_init__(self, x):
            print(f"Pre-init received x={x}")
            # We can't easily check if it was called without a mock, 
            # but if it's called without args, it will raise TypeError.
            # To verify it works, we can just let it run.
            # To be sure, we can use a side effect.
            B._called = False
            def wrapper(self, x):
                B._called = True
            # This is tricky because we are redefining the method.
            # Let's use a simple check.

    # If the fix is not applied, B(1) will raise TypeError: 
    # __attrs_pre_init__() missing 1 required positional argument: 'x'
    b = B(1)

def test_pre_init_with_args_and_kwargs():
    @attr.s
    class C:
        x: int
        def __attrs_pre_init__(self, *args, **kwargs):
            C.args = args
            C.kwargs = kwargs

    c = C(1)
    assert C.args == (1,)
    assert C.kwargs == {}

